/**
 * WICKET-5056
 */
@Test
void optionalParameterGetsLowerScore_ThanExactOne() throws Exception {
    final Url url = Url.parse("all/sindex");
    final MountedMapper exactMount = new MountedMapper("/all/sindex", MockPage.class);
    final MountedMapper optionalParameter = new MountedMapper("/all/#{exp}", MockPage.class);
    Request request = getRequest(url);
    final int exactCompatScore = exactMount.getCompatibilityScore(request);
    final int optCompatScore = optionalParameter.getCompatibilityScore(request);
    assertTrue(exactCompatScore > optCompatScore, "exactCompatScore should have greater compatibility score than optional one" + " got exact = " + exactCompatScore + " and optional = " + optCompatScore);
}

@Test
void exactMountGetsBetterScore_ThanParameterOne() throws Exception {
    final Url url = Url.parse("all/sindex");
    final MountedMapper exactMount = new MountedMapper("/all/sindex", MockPage.class);
    final MountedMapper requiredParam = new MountedMapper("/all/${exp}", MockPage.class);
    Request request = getRequest(url);
    final int exactCompatScore = exactMount.getCompatibilityScore(request);
    final int requiredParamScore = requiredParam.getCompatibilityScore(request);
    assertTrue(exactCompatScore > requiredParamScore, "exactCompatScore should have greater compatibility score than required one" + " got exact = " + exactCompatScore + " and required= " + requiredParamScore);
}

@Test
void exactMountGetsBetterScore_ThanParameterOne_ThenOptionalOne() throws Exception {
    final Url url = Url.parse("all/sindex");
    final MountedMapper exactMount = new MountedMapper("/all/sindex", MockPage.class);
    final MountedMapper requiredParam = new MountedMapper("/all/${exp}", MockPage.class);
    final MountedMapper optionalParameter = new MountedMapper("/all/#{exp}", MockPage.class);
    final MountedMapper requiredOptionalParam = new MountedMapper("/all/${exp}/#{opt}", MockPage.class);
    Request request = getRequest(url);
    final int exactCompatScore = exactMount.getCompatibilityScore(request);
    final int requiredParamScore = requiredParam.getCompatibilityScore(request);
    final int optCompatScore = optionalParameter.getCompatibilityScore(request);
    final int requiredOptCompatScore = requiredOptionalParam.getCompatibilityScore(request);
    // all the mappers above must be eligible for the give URL (i.e. their score must be > 0)
    assertTrue(exactCompatScore > 0, "exactMount mapper must be eligible to handle the request");
    assertTrue(requiredParamScore > 0, "requiredParam mapper must be eligible to handle the request");
    assertTrue(optCompatScore > 0, "optionalParameter mapper must be eligible to handle the request");
    assertTrue(requiredOptCompatScore > 0, "requiredOptionalParam mapper must be eligible to handle the request");
    assertTrue(exactCompatScore > requiredParamScore, "exactCompatScore should have greater compatibility score than required one" + " got exact = " + exactCompatScore + " and required= " + requiredParamScore);
    assertTrue(exactCompatScore > requiredOptCompatScore, "exactCompatScore should have greater compatibility score than required+optional one" + " got exact = " + exactCompatScore + " and requiredOptional= " + requiredOptCompatScore);
    assertTrue(requiredParamScore > optCompatScore, "exactCompatScore should have greater compatibility score than optional one" + " got exact = " + exactCompatScore + " and optional = " + optCompatScore);
}

