        if (i == 0) {
            assertTrue(srcSetElement.endsWith("320w"));
        }
        if (i == 1) {
            assertTrue(srcSetElement.endsWith("2x"));
        }
        if (i == 2) {
            assertTrue(srcSetElement.endsWith("900w"));
        }
        i++;
    }
