@Test
public void testConcurrentModifications() throws Exception {
    final WebApplication application = new MockApplication();
    final MockHttpSession httpSession = new MockHttpSession(new MockServletContext(application, ""));
    //prepare servlet context
    final WicketTester wicketTester = new PageStoringWicketTester(application, true) {

        @Override
        public MockHttpSession getHttpSession() {
            return httpSession;
        }
    };
    wicketTester.executeUrl("/");
    ExecutorService executor = Executors.newFixedThreadPool(1000);
    Callable<Void> executeURLTask = () -> {
        final WicketTester parallelWicketTester;
        synchronized (application) {
            parallelWicketTester = new PageStoringWicketTester(application, false) {

                @Override
                public MockHttpSession getHttpSession() {
                    return httpSession;
                }
            };
        }
        parallelWicketTester.executeUrl("/");
        return null;
    };
    Callable<Void> serializeSessionTask = () -> {
        final NullOutputStream nullOutputStream = NullOutputStream.NULL_OUTPUT_STREAM;
        try (final ObjectOutputStream objectOutputStream = new ObjectOutputStream(nullOutputStream)) {
            objectOutputStream.writeObject(wicketTester.getSession());
        } catch (final IOException e) {
            throw new RuntimeException(e);
        }
        return null;
    };
    var tasks = Stream.concat(IntStream.rangeClosed(1, 500).mapToObj(i -> serializeSessionTask), IntStream.rangeClosed(1, 500).mapToObj(i -> executeURLTask)).collect(Collectors.toList());
    var futures = executor.invokeAll(tasks);
    futures.forEach(exceptionFuture -> {
        try {
            exceptionFuture.get();
        } catch (InterruptedException | ExecutionException e) {
            throw new RuntimeException(e);
        }
    });
}

@Test
void testAdd() {
    MockPageStore mockStore = new MockPageStore();
    MockPageContext context = new MockPageContext();
    RequestPageStore store = new RequestPageStore(mockStore);
    MockPage page1 = new MockPage(1);
    MockPage page2 = new MockPage(2);
    MockPage page3 = new MockPage(3);
    store.addPage(context, page1);
    store.addPage(context, page2);
    store.addPage(context, page3);
    assertTrue(mockStore.getPages().isEmpty(), "no pages delegated before detach");
    store.detach(context);
    assertEquals(3, mockStore.getPages().size(), "pages delegated on detach");
    mockStore.getPages().clear();
    assertNull(store.getPage(context, 1), "no page in request store");
    assertNull(store.getPage(context, 2), "no page in request store");
    assertNull(store.getPage(context, 3), "no page in request store");
}

