    Assert.assertFalse(hangman.isLost());
    doGuessTest(hangman, 's', true);
    Assert.assertEquals(4, hangman.getGuessesRemaining());
    Assert.assertFalse(hangman.isWon());
    Assert.assertFalse(hangman.isLost());
    doGuessTest(hangman, 'i', true);
    Assert.assertEquals(4, hangman.getGuessesRemaining());
