@Test
public void defaultAlphabet() {
    Set<String> encoded = new HashSet<>();
    for (int i = -10000; i < 10000; i++) {
        String enc = LongEncoder.encode(i);
        assertFalse(encoded.contains(enc), "uniqueness: " + i);
