/**
 * Test parsing of comma separated variables.
 */
@Test
public void commaSeparatedVariableParser() {
    CommaSeparatedVariableParser parser = new CommaSeparatedVariableParser("a,b,c");
    assertTrue(parser.matches());
    assertEquals(3, parser.getValues().size());
    assertEquals("a", parser.getValues().get(0));
    assertEquals("b", parser.getValues().get(1));
    assertEquals("c", parser.getValues().get(2));
    // no whitespaces will be removed
    parser = new CommaSeparatedVariableParser(" a ,b, c , d ");
    assertTrue(parser.matches());
    assertEquals(4, parser.getValues().size());
    assertEquals(" a ", parser.getValues().get(0));
    assertEquals("b", parser.getValues().get(1));
    assertEquals(" c ", parser.getValues().get(2));
    assertEquals(" d ", parser.getValues().get(3));
    // It'll care for "" and '' but it'll not remove them
    parser = new CommaSeparatedVariableParser("'a ',\" b\",'c,d'");
    assertTrue(parser.matches());
    assertEquals(3, parser.getValues().size());
    assertEquals("'a '", parser.getValues().get(0));
    assertEquals("\" b\"", parser.getValues().get(1));
    assertEquals("'c,d'", parser.getValues().get(2));
    // But no escapes. Because no separator is following the 2nd "'",
    // it'll stop parsing the string.
    parser = new CommaSeparatedVariableParser("'a\'b, c");
    assertTrue(parser.matches());
    assertEquals(1, parser.getValues().size());
    assertEquals("'a'", parser.getValues().get(0));
    parser = new CommaSeparatedVariableParser("a");
    assertTrue(parser.matches());
    assertEquals(1, parser.getValues().size());
    assertEquals("a", parser.getValues().get(0));
    // Empty elements are not supported
    parser = new CommaSeparatedVariableParser("a,,");
    assertTrue(parser.matches());
    assertEquals(1, parser.getValues().size());
    assertEquals("a", parser.getValues().get(0));
}

/**
 * Test the tag parser.
 */
@Test
public void tagParser() {
    String tag = "name";
    TagNameParser parser = new TagNameParser(tag);
    assertEquals(true, parser.matcher().matches());
    assertEquals("name", parser.getName());
    assertNull(parser.getNamespace());
    tag = "namespace:name";
    parser = new TagNameParser(tag);
    assertEquals(true, parser.matcher().matches());
    assertEquals("name", parser.getName());
    assertEquals("namespace", parser.getNamespace());
    tag = "namespace:";
    parser = new TagNameParser(tag);
    assertEquals(false, parser.matcher().matches());
    tag = ":names";
    parser = new TagNameParser(tag);
    // leading : is allowed according to https://www.w3.org/TR/REC-xml/#NT-NameStartChar
    assertTrue(parser.matcher().matches());
}

/**
 * Tests parsing of attribute names with and without namespaces
 *
 * https://issues.apache.org/jira/browse/WICKET-4679
 */
@Test
void parseAttributeName() {
    String tagName = "tagName";
    VariableAssignmentParser parser = new VariableAssignmentParser(tagName + " name='value'");
    assertTrue(parser.matcher().find(tagName.length()));
    assertEquals("name", parser.getKey());
    assertEquals("'value'", parser.getValue());
    parser = new VariableAssignmentParser(tagName + " namespace:name='value'");
    assertTrue(parser.matcher().find(tagName.length()));
    assertEquals("namespace:name", parser.getKey());
    assertEquals("'value'", parser.getValue());
    parser = new VariableAssignmentParser(tagName + " namespace:name:subname='value'");
    assertTrue(parser.matcher().find(tagName.length()));
    assertEquals("namespace:name:subname", parser.getKey());
    assertEquals("'value'", parser.getValue());
}

/**
 * https://issues.apache.org/jira/browse/WICKET-6815
 */
@Test
void testTagAttributeParsing() {
    String tag = "label wicket:id=\"myid\" bind:test=\"test\" v-bind:test2=\"test2\" :test3=\"test3\" @test4=\"test4\"";
    VariableAssignmentParser attributeParser = new VariableAssignmentParser(tag);
    int pos = 5;
    assertTrue(attributeParser.matcher().find(pos));
    String key = attributeParser.getKey();
    String value = attributeParser.getValue();
    pos = attributeParser.matcher().end(0);
    assertEquals("wicket:id", key);
    assertEquals("\"myid\"", value);
    assertTrue(attributeParser.matcher().find(pos));
    key = attributeParser.getKey();
    value = attributeParser.getValue();
    pos = attributeParser.matcher().end(0);
    assertEquals("bind:test", key);
    assertEquals("\"test\"", value);
    assertTrue(attributeParser.matcher().find(pos));
    key = attributeParser.getKey();
    value = attributeParser.getValue();
    pos = attributeParser.matcher().end(0);
    assertEquals("v-bind:test2", key);
    assertEquals("\"test2\"", value);
    assertTrue(attributeParser.matcher().find(pos));
    key = attributeParser.getKey();
    value = attributeParser.getValue();
    pos = attributeParser.matcher().end(0);
    assertEquals(":test3", key);
    assertEquals("\"test3\"", value);
    assertTrue(attributeParser.matcher().find(pos));
    key = attributeParser.getKey();
    value = attributeParser.getValue();
    assertEquals("@test4", key);
    assertEquals("\"test4\"", value);
}

